package runner

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"os"
	"strconv"
	"time"

	"github.com/sloprail/harness-mocks/claude-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/claude-mock/internal/toolexec"
)

// The Agent tool spawns a nested subagent. Real Claude renamed the Task tool to
// Agent in v2.1.63 but kept Task as an accepted alias, so the mock honours both.
// sr:docs https://code.claude.com/docs/en/sub-agents
const (
	toolNameAgent = "Agent"
	toolNameTask  = "Task"
)

// envSubagentScript names the fallback subagent scenario script used when an
// Agent tool_use does not carry an explicit `script` field.
const envSubagentScript = "A10N_MOCK_SUBAGENT_SCRIPT"

// envStopHookBlockCap is the REAL Claude Code environment variable that controls
// how many CONSECUTIVE times a Stop/SubagentStop hook may block the turn from
// ending before Claude Code overrides it. Default is 8; 0 disables the cap
// (unlimited); raise it when a hook needs more iterations to resolve. The mock
// honours the same variable + default so it imitates production exactly. This is
// DISTINCT from the task's metadata.max_retries (the executor's verify budget):
// both exist in parallel — max_retries bounds verify attempts (the hook stops
// blocking once it's spent), this caps the hook-block loop itself as a backstop.
// sr:docs https://code.claude.com/docs/en/env-vars
// sr:docs https://code.claude.com/docs/en/hooks#subagentstop
const envStopHookBlockCap = "CLAUDE_CODE_STOP_HOOK_BLOCK_CAP"

const defaultStopHookBlockCap = 8

// stopHookBlockCap reads CLAUDE_CODE_STOP_HOOK_BLOCK_CAP (default 8). A returned
// 0 means "no cap" (the env was set to 0): callers treat 0 as unlimited.
func stopHookBlockCap() int {
	if v := os.Getenv(envStopHookBlockCap); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n >= 0 {
			return n
		}
	}
	return defaultStopHookBlockCap
}

// isAgentTool reports whether toolName is the Agent tool or its Task alias.
func isAgentTool(toolName string) bool {
	return toolName == toolNameAgent || toolName == toolNameTask
}

// agentToolInput is the subset of the Agent (alias Task) tool_use input the mock
// understands. The real claude binary emits {description, prompt, subagent_type,
// isolation}; the mock additionally accepts a `script` field naming the subagent's
// scenario script (real claude lets the LLM decide subagent behaviour — the mock
// cannot, so the test supplies a script, mirroring the top-level --script).
// sr:docs https://code.claude.com/docs/en/sub-agents
type agentToolInput struct {
	Description  string `json:"description,omitempty"`
	Prompt       string `json:"prompt,omitempty"`
	SubagentType string `json:"subagent_type,omitempty"`
	// Isolation="worktree" makes the mock REPORT the subagent's isolated worktree cwd
	// (<parent>/.claude/worktrees/agent-<id>) in the SubagentStart/Stop payloads and the
	// seeded transcript — matching real claude, where the subagent's os.Getwd() differs
	// from the parent while the session_id stays shared. The mock does not physically
	// bind a git worktree (its internal machinery stays on the parent cwd); it only
	// mirrors the OBSERVED identity. Any other isolation value shares the parent cwd.
	Isolation string `json:"isolation,omitempty"`
	// Model is the optional model override the real Agent input accepts; the
	// mock reports it as an async receipt's resolvedModel.
	Model string `json:"model,omitempty"`
	// Script is the absolute path to the subagent's scenario script (mock-only).
	Script string `json:"script,omitempty"`
}

// runAgentTool runs a foreground Agent (alias Task) call, the way the real
// claude binary handles one:
//  1. Validate the input: description and prompt are required strings (the
//     2.1.282 Agent input schema); a call without them is refused with an
//     InputValidationError tool_result and nothing runs.
//  2. Mint the agent id and seed the sub-agent's own transcript
//     (<session>/subagents/agent-<id>.jsonl) with the dispatch prompt.
//  3. Fire SubagentStart. It cannot block: an exit 2 is recorded in the
//     sub-agent's own transcript as a non-blocking error and the sub-agent
//     runs anyway (docs, "Exit code 2 behavior per event"; a controlled
//     2.1.282 run).
//  4. Run the sub-agent, then fire SubagentStop. A SubagentStop block re-runs
//     the sub-agent with the feedback, as real Claude Code keeps a sub-agent
//     running, up to CLAUDE_CODE_STOP_HOOK_BLOCK_CAP. What the hook said is
//     recorded in the sub-agent's own file.
//  5. Return the tool_result real Claude Code returns for a finished
//     foreground sub-agent (buildAgentResult).
//
// toolUseID is the id of the Agent/Task tool_use that spawned the sub-agent;
// real Claude Code records it as the toolUseId of the sub-agent's .meta.json.
//
// sr:docs https://code.claude.com/docs/en/sub-agents
// sr:docs https://code.claude.com/docs/en/hooks#subagentstart
func runAgentTool(ctx context.Context, cfg Config, inv *hooks.Invoker, toolUseID string, rawInput json.RawMessage, tr *transcript) toolexec.Result {
	sub, _, errRes := prepareSubagent(ctx, cfg, inv, toolUseID, rawInput, tr, false)
	if sub == nil {
		return errRes
	}
	started := time.Now()
	out := sub.execute(ctx, inv, cfg.bg, sub.prompt)
	var in agentToolInput
	_ = json.Unmarshal(rawInput, &in)
	worktree := ""
	if sub.subCwd != cfg.Cwd && !sub.cleanupWorktree(ctx) {
		worktree = sub.subCwd
	}
	return buildAgentResult(sub, in, cfg.Model, out, time.Since(started).Milliseconds(), worktree)
}

// resolveSubagentScript picks the subagent scenario script: the Agent input's
// `script` field wins, then the A10N_MOCK_SUBAGENT_SCRIPT env var, else "".
// sr:invariant subagent-script
func resolveSubagentScript(fromInput string) string {
	if fromInput != "" {
		return fromInput
	}
	return os.Getenv(envSubagentScript)
}

// newAgentID returns an agent id in the shape real Claude Code mints: "a"
// followed by 16 hex digits (every agentId in the real transcripts, e.g.
// a1e3c03d8ae9ab06a).
func newAgentID() (string, error) {
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return "a" + hex.EncodeToString(b[:]), nil
}
// Package scenario runs the script that drives a mock: once per turn, it
// prints stream-json lines that say what the agent does.
package scenario

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"

	"github.com/sloprail/harness-mocks/internal/procexec"
)

// Input is what the script is told on each run, in A10N_MOCK_* variables.
type Input struct {
	// Prompt is the user's prompt, unchanged.
	Prompt string
	// AdditionalContext is the context a UserPromptSubmit hook added.
	AdditionalContext string
	// SessionFile is the session record so far.
	SessionFile string
}

// ToolUse is a tool call the script asked for.
type ToolUse struct {
	ID    string
	Name  string
	Input json.RawMessage
}

// Turn is what one run of the script said: the agent's messages in order, and
// how the turn ends, with a tool call or with the result that ends the run
// (neither: the script ended without a tool call or a result).
type Turn struct {
	Texts  []string
	Tool   *ToolUse
	Result *string
}

// Idents are the variables a script is given.
//
// The script receives the user's prompt, unchanged, in A10N_MOCK_PROMPT; the
// session record so far in A10N_MOCK_SESSION_FILE; and a UserPromptSubmit
// hook's additional context in A10N_MOCK_ADDITIONAL_CONTEXT, never in place of
// the prompt.
//
// sr:invariant scenario-prompt-env
// sr:invariant session-file-env
// sr:invariant prompt-context-appended
func Idents(in Input) map[string]string {
	return map[string]string{
		"A10N_MOCK_PROMPT":             in.Prompt,
		"A10N_MOCK_ADDITIONAL_CONTEXT": in.AdditionalContext,
		"A10N_MOCK_SESSION_FILE":       in.SessionFile,
	}
}

// RunTurn runs the script once and reads its lines up to the first tool call
// or result.
//
// The script runs once per turn and prints stream-json lines: a tool_use line
// ends the turn, the mock runs the tool and runs the script again; a result
// line ends the run.
//
// sr:invariant turn-loop
func RunTurn(ctx context.Context, script, dir string, environ []string, in Input) (Turn, error) {
	res, err := procexec.Run(ctx, procexec.Spec{
		Argv: []string{"/bin/sh", script}, Dir: dir, Env: procexec.Env(environ, Idents(in), nil),
	})
	if err != nil {
		return Turn{}, fmt.Errorf("codex-mock: cannot run the scenario script: %w", err)
	}
	var t Turn
	sc := bufio.NewScanner(bytes.NewReader(res.Stdout))
	sc.Buffer(make([]byte, 64*1024), 16*1024*1024)
	for sc.Scan() {
		line := bytes.TrimSpace(sc.Bytes())
		if len(line) == 0 {
			continue
		}
		done, err := t.read(line)
		if err != nil {
			return Turn{}, fmt.Errorf("codex-mock: scenario script printed an invalid line: %w\nline: %s", err, line)
		}
		if done {
			break
		}
	}
	return t, nil
}
// Package toolcall is the harness-neutral order of one tool call: validate,
// ask the before-tool hooks, run, tell the after-tool hooks.
package toolcall

import (
	"context"
	"encoding/json"

	"github.com/sloprail/harness-mocks/internal/hooks"
)

// Call is a tool call the agent made.
type Call struct {
	ID    string
	Name  string
	Input json.RawMessage
}

// Result is what a tool that ran produced.
type Result struct {
	Output string
	// Failed: it ran and failed (a command exiting non-zero).
	Failed bool
}

// Kind is how a call ended, which decides what the agent is told.
type Kind int

const (
	// Unknown: the harness has no such tool.
	Unknown Kind = iota
	// Invalid: the input lacks required parameters (Answer.Missing).
	Invalid
	// Refused: a before-tool hook refused it (Answer.Reason); it did not run.
	Refused
	// Done: it ran (Answer.Result), perhaps with its result replaced
	// (Answer.Feedback).
	Done
)

// Answer is the end of a call, handed to the host to tell the agent in its
// own words.
type Answer struct {
	Kind     Kind
	Missing  []string
	Reason   string
	Result   Result
	Feedback string
	// Replaced: an after-tool hook gave Feedback in place of the result.
	Replaced bool
}

// Host is the harness side of a tool call: its tools, its hooks, and how it
// words what the agent is told.
type Host interface {
	// Tool is the parameters a call to the named tool must carry, and whether
	// the harness has the tool.
	Tool(name string) (required []string, known bool)
	// Before asks the before-tool hooks whether they refuse the call.
	Before(ctx context.Context, c Call) (refused bool, reason string)
	// Execute runs the call.
	Execute(ctx context.Context, c Call) Result
	// After tells the hooks of the given kind about a call that ran, and
	// returns the feedback of one that blocks.
	After(ctx context.Context, c Call, r Result, kind hooks.AfterTool) (feedback string, blocked bool)
	// Answer tells the agent how the call ended; Run calls it exactly once.
	Answer(c Call, a Answer)
}

// Options are the parts of the order that differ between harnesses.
type Options struct {
	// SeparateFailureHook: the harness has a hook for a call that failed, which
	// fires instead of the success hook; without one, the success hook fires
	// for a failed call too.
	SeparateFailureHook bool
	// FailureOnRefusal: a call a before-tool hook refused fires the failure
	// hook (SeparateFailureHook), reporting the refusal as a failed call;
	// without it, a refused call fires no after-tool hook.
	FailureOnRefusal bool
}

// Run carries out one call. A call to a tool the harness lacks, and one whose
// input lacks required parameters, end before any hook. A call a before-tool
// hook refuses does not run and fires no after-tool hook (but the failure
// hook, with Options.FailureOnRefusal). A call that ran
// fires the after-tool hook its outcome calls for; a hook that blocks it
// replaces the result the agent sees, and the call has run.
func Run(ctx context.Context, h Host, c Call, o Options) {
	required, known := h.Tool(c.Name)
	if !known {
		h.Answer(c, Answer{Kind: Unknown})
		return
	}
	if missing := hooks.RejectedInput(c.Input, required); len(missing) > 0 {
		h.Answer(c, Answer{Kind: Invalid, Missing: missing})
		return
	}
	if refused, reason := h.Before(ctx, c); refused {
		if o.FailureOnRefusal && o.SeparateFailureHook {
			h.After(ctx, c, Result{Output: reason, Failed: true}, hooks.AfterFailure)
		}
		h.Answer(c, Answer{Kind: Refused, Reason: reason})
		return
	}
	r := h.Execute(ctx, c)
	outcome := hooks.ToolSucceeded
	if r.Failed {
		outcome = hooks.ToolFailed
	}
	kind := hooks.AfterToolHook(outcome)
	if kind == hooks.AfterFailure && !o.SeparateFailureHook {
		kind = hooks.AfterSuccess
	}
	feedback, blocked := h.After(ctx, c, r, kind)
	h.Answer(c, Answer{Kind: Done, Result: r, Feedback: feedback, Replaced: blocked})
}
