// sr:provides tool-failure-hook/cursor
// sr:provides posttooluse-payload/cursor
// sr:docs https://cursor.com/docs/hooks#posttoolusefailure
func (h *toolHost) After(ctx context.Context, _ toolcall.Call, _ toolcall.Result, kind corehooks.AfterTool) (string, bool) {
	own := hooks.ToolFields(h.tool)
	own["duration"] = ms(h.res.Took)
	if h.refused {
		own["error_message"], own["failure_type"], own["is_interrupt"] = h.failure, "permission_denied", false
		h.s.keep(h.s.hooks.Fire(ctx, hooks.PostToolUseFailure, h.tool.Name, own))
		return "", false
	}
	switch {
	case h.call.Kind == "shellToolCall":
		h.s.hooks.Fire(ctx, hooks.AfterShellExecution, h.call.Command(), map[string]any{
			"command": h.call.Command(), "output": h.res.Output, "duration": ms(h.res.Took), "sandbox": false})
	case h.call.Kind == "editToolCall" && !h.res.Failed:
		h.s.hooks.Fire(ctx, hooks.AfterFileEdit, "Write", map[string]any{"file_path": h.call.Path(h.s.cfg.Dir), "edits": h.res.Edits})
	}
	switch kind {
	case corehooks.AfterSuccess:
		own["tool_output"] = h.res.ToolOutput
		h.s.keep(h.s.hooks.Fire(ctx, hooks.PostToolUse, h.tool.Name, own))
	case corehooks.AfterFailure:
		own["error_message"], own["failure_type"], own["is_interrupt"] = h.res.ErrorMessage, "error", false
		h.s.keep(h.s.hooks.Fire(ctx, hooks.PostToolUseFailure, h.tool.Name, own))
	}
	return "", false
}

// Answer tells the agent how a call that did not run ended: refused by a hook,
// a tool the mock does not have, or input that lacks parameters (no hook
// fires for the last two; their wording is the mock's own).
func (h *toolHost) Answer(c toolcall.Call, a toolcall.Answer) {
	switch a.Kind {
	case toolcall.Refused:
		h.emit(rejectedFrame(h.s.id, c.ID, h.call, h.result))
	case toolcall.Unknown:
		h.emit(errorFrame(h.s.id, c.ID, toolexec.Call{Kind: "unknownToolCall"}, "Unknown tool: "+c.Name))
	case toolcall.Invalid:
		h.emit(errorFrame(h.s.id, c.ID, toolexec.FromScript(c.Name, c.Input),
			fmt.Sprintf("%s: missing required parameter(s): %s", c.Name, strings.Join(a.Missing, ", "))))
	}
}

package runner

import (
	"context"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/toolexec"
	"github.com/sloprail/harness-mocks/internal/scenario"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// SubmitPrompt fires nothing: cursor-agent in print mode was recorded not
// firing beforeSubmitPrompt, so no hook blocks the prompt or adds context.
func (s *session) SubmitPrompt(context.Context) (string, bool) { return "", false }

// Say prints what the agent said, and records it.
func (s *session) Say(text string) {
	s.texts = append(s.texts, text)
	s.tr.text(text)
	s.forward(assistantFrame(s.id, text))
}

// EndOfTurn fires nothing: cursor-agent in print mode was recorded not firing
// the stop hook, so nothing blocks the end of the turn.
func (s *session) EndOfTurn(context.Context, string, bool) (string, bool) { return "", false }

// Continue is never asked for: no end-of-turn hook blocks.
func (s *session) Continue(string) {}

// CapOverridden is never asked for: no end-of-turn hook blocks, so there is no
// cap to reach.
func (s *session) CapOverridden(int) {}

// SessionFile is the conversation's transcript so far.
func (s *session) SessionFile() string { return s.tr.path }

// Tool carries out a call the script made: it is printed as started, run
// through the shared order of a tool call, and recorded. A write first reads
// the file it is about to change: a call of its own to the hooks (recorded:
// runs/tool-failure, runs/file-tools), which is not shown on the stream.
func (s *session) Tool(ctx context.Context, tu scenario.ToolUse) {
	c := toolexec.FromScript(tu.Name, tu.Input)
	s.forward(startedFrame(s.id, tu.ID, c))
	s.tr.toolUse(tu.Name, c.Args)
	if c.Kind == "editToolCall" {
		path := map[string]any{"file_path": c.Args["path"]}
		s.runTool(ctx, scenario.ToolUse{ID: tu.ID + "-read", Name: "Read", Input: jsonLine(path)}, true)
	}
	s.runTool(ctx, tu, false)
}

// runTool runs one call through the shared order; quiet leaves it off the
// stream.
func (s *session) runTool(ctx context.Context, tu scenario.ToolUse, quiet bool) {
	h := &toolHost{s: s, quiet: quiet}
	toolcall.Run(ctx, h, toolcall.Call{ID: tu.ID, Name: tu.Name, Input: tu.Input},
		toolcall.Options{SeparateFailureHook: true, FailureOnRefusal: true})
}
package runner

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// transcript is the conversation's record file, in the layout Cursor keeps
// (recorded: runs/*/samples/*/transcript): one JSON line per message, a user
// message first, assistant messages with their text and tool calls, and a
// closing turn_ended line. It is what the scenario script reads as
// A10N_MOCK_SESSION_FILE.
type transcript struct{ path string }

var nonAlnum = regexp.MustCompile(`[^A-Za-z0-9]`)

// newTranscript names the session's file under <home>/.cursor/projects/<project>/
// agent-transcripts/<session>/, where <project> is the workspace path (symlinks
// resolved by the entrypoint) with every non-alphanumeric character as "-". The
// file itself is written with the first record, after the start hook has run.
//
// sr:provides session-transcript-file/cursor
// sr:docs https://cursor.com/docs/hooks#common-schema
func newTranscript(home, dir, session string) (*transcript, error) {
	project := nonAlnum.ReplaceAllString(strings.TrimPrefix(dir, "/"), "-")
	d := filepath.Join(home, ".cursor", "projects", project, "agent-transcripts", session)
	if err := os.MkdirAll(d, 0o755); err != nil {
		return nil, err
	}
	return &transcript{path: filepath.Join(d, session+".jsonl")}, nil
}

func (t *transcript) add(line any) {
	b, _ := json.Marshal(line)
	if f, err := os.OpenFile(t.path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644); err == nil {
		_, _ = f.Write(append(b, '\n'))
		_ = f.Close()
	}
}

func (t *transcript) message(role string, blocks ...map[string]any) {
	t.add(map[string]any{"role": role, "message": map[string]any{"content": blocks}})
}

func (t *transcript) user(prompt string) {
	t.message("user", map[string]any{"type": "text", "text": "<user_query>\n" + prompt + "\n</user_query>"})
}

func (t *transcript) text(s string) {
	t.message("assistant", map[string]any{"type": "text", "text": s})
}

func (t *transcript) toolUse(name string, input map[string]any) {
	t.message("assistant", map[string]any{"type": "tool_use", "name": name, "input": input})
}

func (t *transcript) end() { t.add(map[string]any{"type": "turn_ended", "status": "success"}) }

func (t *transcript) exists() bool { _, err := os.Stat(t.path); return err == nil }
package runner

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/procexec"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// session is one run's state, and the harness side (turnloop.Host) of its turn.
type session struct {
	cfg     Config
	id      string
	tr      *transcript
	hooks   *hooks.Hooks
	started time.Time
	texts   []string // what the agent said, in order: the result frame's text
	// named: hook payloads carry the transcript path. Cursor leaves it null
	// until the conversation's first tool call is past its preToolUse hooks
	// (recorded: runs/tool-failure), though the file is there from the first
	// record.
	named bool
	// added is the context the hooks have handed the agent so far (their
	// additional_context), in the order their events fired and, within an event,
	// the order the hooks are configured in.
	added []string
}

// keep adds the context the hooks of one event gave to the agent's: all of it,
// when several hooks gave some.
//
// sr:provides hook-additional-context/cursor
func (s *session) keep(ds []hooks.Decision) {
	for _, d := range ds {
		if d.Context != "" {
			s.added = append(s.added, d.Context)
		}
	}
}

// Context is what the agent has been handed by hooks, all of it (turnloop.Params.Added).
func (s *session) Context() string { return strings.Join(s.added, "\n") }

// Run plays one run: the stream's opening frames, the sessionStart hooks, the
// script's turns until its result, the sessionEnd hooks, and then the result
// frame, last on the stream. A single prompt runs to completion without
// interaction, streaming one record per line and ending with one result. The
// sessionEnd hook says the session completed: a non-interactive run has no
// other reason to report.
//
// The sessionStart hook fires once, before the first turn, and what it prints or
// exits with does not stop the session (recorded: runs/session-start-block); the
// payload says no source, as Cursor's does not.
//
// sr:provides noninteractive-run/cursor
// sr:provides session-end-hook/cursor
// sr:provides session-start-hook/cursor
// sr:docs https://cursor.com/docs/hooks#sessionend
// sr:docs https://cursor.com/docs/hooks#sessionstart
func Run(ctx context.Context, cfg Config) error {
	s := &session{cfg: cfg, id: coresession.NewID(), started: time.Now()}
	var err error
	if s.tr, err = newTranscript(cfg.Home, cfg.Dir, s.id); err != nil {
		return fmt.Errorf("cursor-mock: %w", err)
	}
	conf, err := hooks.Load(cfg.Dir)
	if err != nil {
		return fmt.Errorf("cursor-mock: %w", err)
	}
	s.hooks = &hooks.Hooks{Config: conf, Dir: cfg.Dir, Env: s.hookEnv, Common: s.common}
	s.forward(initFrame(s.id, cfg.Dir))
	s.forward(userFrame(s.id, cfg.Prompt))
	s.keep(s.hooks.Fire(ctx, hooks.SessionStart, hooks.NoSubject, map[string]any{"is_background_agent": false}))
	s.tr.user(cfg.Prompt) // the transcript file does not exist yet when the start hook runs
	_, runErr := turnloop.Run(ctx, s, turnloop.Params{Script: cfg.Script, Dir: cfg.Dir, Environ: cfg.Environ, Prompt: cfg.Prompt, Added: s.Context})
	s.named = true
	s.hooks.Fire(ctx, hooks.SessionEnd, hooks.NoSubject, map[string]any{
		"reason": "completed", "duration_ms": time.Since(s.started).Milliseconds(),
		"is_background_agent": false, "final_status": "completed",
	})
	s.tr.end()
	if runErr != nil {
		return fmt.Errorf("cursor-mock: %w", runErr)
	}
	s.forward(resultFrame(s.id, strings.Join(s.texts, ""), time.Since(s.started)))
	return nil
}

// hookEnv is the environment of a hook command: the harness's own, with the
// facts Cursor gives a hook (recorded: runs/subprocess-session-env,
// runs/nested-session-env).
func (s *session) hookEnv() []string {
	return procexec.Env(s.cfg.Environ,
		childenv.HookIdentity(s.cfg.Dir, s.common().TranscriptPath), childenv.HookDefaults(s.cfg.Dir, s.cfg.Version))
}

// common is what every hook payload carries now: the transcript path only once
// the conversation has a transcript.
func (s *session) common() hooks.Common {
	c := hooks.Common{SessionID: s.id, Dir: s.cfg.Dir, Version: s.cfg.Version}
	if s.named && s.tr.exists() {
		c.TranscriptPath = s.tr.path
	}
	return c
}

// forward prints one stream-json line.
func (s *session) forward(line []byte) { fmt.Fprintf(s.cfg.Stdout, "%s\n", line) }

// Package events is the JSONL event stream `codex exec --json` prints.
package events

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// Stream writes the events of one run, one JSON object per line.
type Stream struct {
	out  io.Writer
	next int
}

// New is a stream on out.
func New(out io.Writer) *Stream { return &Stream{out: out} }

func (s *Stream) emit(v map[string]any) {
	enc := json.NewEncoder(s.out)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func (s *Stream) newID() string {
	id := fmt.Sprintf("item_%d", s.next)
	s.next++
	return id
}

// ThreadStarted opens the run: the thread is the session.
func (s *Stream) ThreadStarted(id string) {
	s.emit(map[string]any{"type": "thread.started", "thread_id": id})
}

// TurnStarted opens a turn: from the user's prompt to the final message.
func (s *Stream) TurnStarted() { s.emit(map[string]any{"type": "turn.started"}) }

// TurnCompleted closes the turn. The mock calls no model, so it used no tokens.
func (s *Stream) TurnCompleted() {
	s.emit(map[string]any{"type": "turn.completed", "usage": map[string]int{
		"input_tokens": 0, "cached_input_tokens": 0, "cache_write_input_tokens": 0,
		"output_tokens": 0, "reasoning_output_tokens": 0}})
}

// AgentMessage reports a message from the agent.
func (s *Stream) AgentMessage(text string) {
	s.emit(map[string]any{"type": "item.completed", "item": map[string]any{
		"id": s.newID(), "type": "agent_message", "text": text}})
}

// ShellCommand is how Codex shows a command the shell ran.
func ShellCommand(command string) string {
	return "/bin/sh -c '" + strings.ReplaceAll(command, "'", `'\''`) + "'"
}

// CommandStarted reports a command that began; the id pairs it with its end.
func (s *Stream) CommandStarted(command string) string {
	id := s.newID()
	s.emit(map[string]any{"type": "item.started", "item": map[string]any{
		"id": id, "type": "command_execution", "command": ShellCommand(command),
		"aggregated_output": "", "exit_code": nil, "status": "in_progress"}})
	return id
}

// CommandCompleted reports how a started command ended: its exit status and
// everything it printed, and a status of completed on exit 0, failed otherwise
// (recorded: runs/shell-exit-status). The agent is told the output as it is,
// failed or not; the failure shows only here.
// sr:provides bash-tool-result/codex
func (s *Stream) CommandCompleted(id, command, output string, exit int) {
	status := "completed"
	if exit != 0 {
		status = "failed"
	}
	s.emit(map[string]any{"type": "item.completed", "item": map[string]any{
		"id": id, "type": "command_execution", "command": ShellCommand(command),
		"aggregated_output": output, "exit_code": exit, "status": status}})
}
// Package session is the rollout file a codex-mock session leaves under
// $CODEX_HOME/sessions, which a scenario script reads as it goes.
package session

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// File is a session's append-only rollout: one JSON record per line.
type File struct {
	Path string
	f    *os.File
}

// Create starts the rollout of session id at
// <home>/sessions/YYYY/MM/DD/rollout-<time>-<id>.jsonl, with its meta record.
func Create(home, id, cwd string, now time.Time) (*File, error) {
	dir := filepath.Join(home, "sessions", now.Format("2006"), now.Format("01"), now.Format("02"))
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	path := filepath.Join(dir, fmt.Sprintf("rollout-%s-%s.jsonl", now.Format("2006-01-02T15-04-05"), id))
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	s := &File{Path: path, f: f}
	s.append("session_meta", map[string]any{"id": id, "session_id": id, "cwd": cwd,
		"originator": "codex_exec", "source": "exec", "cli_version": "mock"})
	return s, nil
}

func (s *File) append(kind string, payload map[string]any) {
	enc := json.NewEncoder(s.f)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(map[string]any{"timestamp": time.Now().UTC().Format(time.RFC3339Nano), "type": kind, "payload": payload})
}

func message(role, ctype, text string) map[string]any {
	return map[string]any{"type": "message", "role": role,
		"content": []map[string]string{{"type": ctype, "text": text}}}
}

// User records a user message: the prompt, or the text a hook sent in its place.
func (s *File) User(text string) { s.append("response_item", message("user", "input_text", text)) }

// Developer records context a hook added.
func (s *File) Developer(text string) {
	s.append("response_item", message("developer", "input_text", text))
}

// Assistant records a message from the agent.
func (s *File) Assistant(text string) {
	s.append("response_item", message("assistant", "output_text", text))
}

// ToolCall records a tool call the agent made.
func (s *File) ToolCall(callID, name string, input json.RawMessage) {
	s.append("response_item", map[string]any{"type": "function_call", "call_id": callID, "name": name, "arguments": string(input)})
}

// ToolOutput records what the agent was told a tool call returned.
func (s *File) ToolOutput(callID, output string) {
	s.append("response_item", map[string]any{"type": "function_call_output", "call_id": callID, "output": output})
}

// Close ends the rollout.
func (s *File) Close() error { return s.f.Close() }
package e2e

import (
	"bytes"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// scenario is one mock run: the hooks it loads, the script that drives it.
type scenario struct {
	// HooksJSON is the user layer's $CODEX_HOME/hooks.json.
	HooksJSON string
	// Files are written into the repository (a hook script, say), mode 0755.
	Files map[string]string
	// Script is the scenario script.
	Script string
	Prompt string
	// Env is added to the mock's environment.
	Env []string
	// NoJSON runs `exec` without --json, so stdout carries the final message.
	NoJSON bool
}

// result is what a run left.
type result struct {
	Repo, Home, Tmp string
	Stdout, Stderr  string
	Code            int
}

// execMock runs `exec --json` in a fresh git repository, hermetic but for the
// tools (sh, git, jq) the hooks use: no CODEX_* or CLAUDE* variable of the
// process running the tests reaches it.
func execMock(t *testing.T, s scenario) result {
	t.Helper()
	root, err := filepath.EvalSymlinks(t.TempDir())
	require.NoError(t, err)
	r := result{Repo: filepath.Join(root, "repo"), Home: filepath.Join(root, "home", ".codex"), Tmp: filepath.Join(root, "tmp")}
	for _, d := range []string{r.Repo, r.Home, r.Tmp} {
		require.NoError(t, os.MkdirAll(d, 0o755))
	}
	require.NoError(t, exec.Command("git", "-C", r.Repo, "init", "-q").Run())
	if s.HooksJSON != "" {
		require.NoError(t, os.WriteFile(filepath.Join(r.Home, "hooks.json"), []byte(s.HooksJSON), 0o644))
	}
	for name, body := range s.Files {
		require.NoError(t, os.WriteFile(filepath.Join(r.Repo, name), []byte(body), 0o755))
	}
	script := filepath.Join(root, "scenario.sh")
	require.NoError(t, os.WriteFile(script, []byte(s.Script), 0o755))

	env := []string{"CODEX_HOME=" + r.Home, "TMPDIR=" + r.Tmp, "HOOK_LOG=" + filepath.Join(r.Tmp, "hook.log")}
	for _, kv := range os.Environ() {
		if !strings.HasPrefix(kv, "CODEX") && !strings.HasPrefix(kv, "CLAUDE") && !strings.HasPrefix(kv, "TMPDIR=") {
			env = append(env, kv)
		}
	}
	args := []string{"exec", "--json", "--skip-git-repo-check", "--script", script, "-m", "mock-model", s.Prompt}
	if s.NoJSON {
		args = append(args[:1], args[2:]...)
	}
	cmd := exec.Command(mockBinary, args...)
	cmd.Dir = r.Repo
	cmd.Env = append(env, s.Env...)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		var exit *exec.ExitError
		require.ErrorAs(t, err, &exit)
		r.Code = exit.ExitCode()
	}
	r.Stdout, r.Stderr = out.String(), errb.String()
	return r
}

// jsonLines parses text as JSON objects, one per line, skipping other lines.
func jsonLines(text string) []map[string]any {
	var out []map[string]any
	for _, l := range strings.Split(text, "\n") {
		var m map[string]any
		if json.Unmarshal([]byte(strings.TrimSpace(l)), &m) == nil && m != nil {
			out = append(out, m)
		}
	}
	return out
}

// hookLog is what the run's hooks wrote to $HOOK_LOG, as objects.
func (r result) hookLog() []map[string]any {
	b, _ := os.ReadFile(filepath.Join(r.Tmp, "hook.log"))
	return jsonLines(string(b))
}

// stream is the event stream the run printed.
func (r result) stream() []map[string]any { return jsonLines(r.Stdout) }

// commands are the shell commands the stream shows as run to completion, in
// order, with their exit codes.
func (r result) commands() (cmds []string, exits []float64) {
	for _, e := range r.stream() {
		item, _ := e["item"].(map[string]any)
		if e["type"] == "item.completed" && item["type"] == "command_execution" {
			cmds = append(cmds, innerCommand(item["command"].(string)))
			exits = append(exits, item["exit_code"].(float64))
		}
	}
	return
}

// innerCommand is the command inside `/bin/<shell> -c[l] '<command>'`.
func innerCommand(shellLine string) string {
	i := strings.Index(shellLine, "'")
	return strings.ReplaceAll(strings.TrimSuffix(shellLine[i+1:], "'"), `'\''`, "'")
}

// rollout is the session file the run wrote.
func (r result) rollout(t *testing.T) string {
	t.Helper()
	var text string
	require.NoError(t, filepath.Walk(filepath.Join(r.Home, "sessions"), func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() {
			b, _ := os.ReadFile(p)
			text = string(b)
		}
		return nil
	}))
	return text
}

// hooksJSON is a hooks.json with one command handler per event, all running
// the same command (the matcher is any).
func hooksJSON(command string, events ...string) string {
	h := map[string]any{}
	for _, ev := range events {
		h[ev] = []any{map[string]any{"hooks": []any{map[string]any{"type": "command", "command": command}}}}
	}
	b, _ := json.Marshal(map[string]any{"hooks": h})
	return string(b)
}

const (
	// callThenResult makes one Bash call per run of the script, taken from
	// $CALLS (one command per line), and then a final message and a result.
	callThenResult = `#!/bin/sh
n=$(grep -c function_call_output "$A10N_MOCK_SESSION_FILE")
cmd=$(sed -n "$((n+1))p" "$CALLS")
if [ -n "$cmd" ]; then
  printf '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"call_%s","name":"Bash","input":{"command":%s}}]}}\n' "$n" "$(printf '%s' "$cmd" | jq -Rs .)"
  exit 0
fi
printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"DONE"}]}}' '{"type":"result","subtype":"success","result":"DONE"}'
`
)

// withCalls is env for callThenResult: the commands it runs, in order.
func withCalls(t *testing.T, cmds ...string) []string {
	t.Helper()
	f := filepath.Join(t.TempDir(), "calls")
	require.NoError(t, os.WriteFile(f, []byte(strings.Join(cmds, "\n")+"\n"), 0o644))
	return []string{"CALLS=" + f}
}
package e2e

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

const runsDir = "../../snapshots/runs"

// recording is one recorded sample of a real `codex exec` run.
type recording struct {
	setup  string   // runs/<name>/setup
	sample string   // runs/<name>/samples/<ts>
	calls  []string // the shell commands the model asked for, in order
}

func loadRecording(t *testing.T, name string) recording {
	t.Helper()
	samples, err := filepath.Glob(filepath.Join(runsDir, name, "samples", "*"))
	require.NoError(t, err)
	require.NotEmpty(t, samples, "no recorded sample of run %s", name)
	rec := recording{setup: filepath.Join(runsDir, name, "setup"), sample: samples[len(samples)-1]}
	seen := map[string]bool{}
	for _, p := range jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))) {
		id, _ := p["tool_use_id"].(string)
		if p["hook_event_name"] == "PreToolUse" && !seen[id] {
			seen[id] = true
			in, _ := p["tool_input"].(map[string]any)
			rec.calls = append(rec.calls, in["command"].(string))
		}
	}
	if len(rec.calls) == 0 { // no before-tool hook logged: the commands that ran are the calls
		rec.calls, _ = result{Stdout: readFile(t, filepath.Join(rec.sample, "stream.jsonl"))}.commands()
	}
	return rec
}

func readFile(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return ""
	}
	require.NoError(t, err)
	return string(b)
}

// replay runs the mock on the recorded run's own setup (its hooks.json, its
// hook script, its prompt), with a script that makes the calls the model made.
func replay(t *testing.T, rec recording, extraEnv ...string) result {
	t.Helper()
	return execMock(t, scenario{
		HooksJSON: readFile(t, filepath.Join(rec.setup, "hooks.json")),
		Files:     map[string]string{"hook.sh": readFile(t, filepath.Join(rec.setup, "hook.sh"))},
		Script:    callThenResult,
		Prompt:    strings.TrimSpace(readFile(t, filepath.Join(rec.setup, "prompt.txt"))),
		Env:       append(withCalls(t, rec.calls...), extraEnv...),
	})
}

// normalized is what a hook payload shows of what a scenario did, without what
// differs between two runs of the same behaviour (ids, paths, timings, the
// model's name, the OS's wording of an error): the same removals capture.sh makes.
func normalized(v any, sid string) any {
	switch x := v.(type) {
	case map[string]any:
		for _, k := range []string{"transcript_path", "cwd", "turn_id", "tool_use_id", "uuid", "timestamp", "duration_ms", "last_assistant_message", "model"} {
			delete(x, k)
		}
		if in, ok := x["tool_input"].(map[string]any); ok {
			delete(in, "description")
		}
		for k, e := range x {
			x[k] = normalized(e, sid)
		}
	case string:
		if strings.Contains(x, "No such file or directory") {
			return "<ENOENT>"
		}
		return strings.ReplaceAll(x, sid, "<SESSION_ID>")
	}
	return v
}

func sortedHookLines(lines []map[string]any) []string {
	var sid string
	for _, l := range lines {
		if s, ok := l["session_id"].(string); ok {
			sid = s
			break
		}
	}
	var out []string
	for _, l := range lines {
		b, _ := json.Marshal(normalized(l, sid))
		out = append(out, string(b))
	}
	sort.Strings(out)
	return out
}

// Every recorded run of the hooks a `codex exec` fires, replayed: the mock's
// hooks see the same payloads, and the hook scripts take the same exits; the
// event stream shows the same commands, run to the same exit statuses and
// outputs, in the same order (a command a hook refused is in neither).
// sr:proves hook-exit-code-semantics/codex
// sr:proves pretooluse-refusal/codex
func TestReplayOfRecordedRuns(t *testing.T) {
	for _, name := range []string{"stops", "hook-exit-codes", "hook-exit-json", "hook-unstartable",
		"pretool-decisions", "prompt-blocked", "posttool-block", "hook-matchers", "hook-timeout", "session-end"} {
		t.Run(name, func(t *testing.T) {
			rec := loadRecording(t, name)
			got := replay(t, rec)
			require.Equal(t, 0, got.Code, got.Stderr)

			var want []map[string]any
			for _, l := range jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))) {
				want = append(want, l)
			}
			assert.Equal(t, sortedHookLines(want), sortedHookLines(got.hookLog()), "hook payloads and exits")

			recStream := result{Stdout: readFile(t, filepath.Join(rec.sample, "stream.jsonl"))}
			wantCmds, wantExits := recStream.commands()
			gotCmds, gotExits := got.commands()
			assert.Equal(t, wantCmds, gotCmds, "commands that ran")
			assert.Equal(t, failures(wantExits), failures(gotExits), "which of them failed (the status of ls differs between systems)")
			assert.Equal(t, streamShape(recStream.stream()), streamShape(got.stream()), "event stream")
		})
	}
}

func failures(exits []float64) []bool {
	var out []bool
	for _, e := range exits {
		out = append(out, e != 0)
	}
	return out
}

// streamShape is the event types of a stream, without the warnings and the
// messages that depend on the run's flags and the model's words.
func streamShape(events []map[string]any) []string {
	var out []string
	for _, e := range events {
		typ, _ := e["type"].(string)
		item, _ := e["item"].(map[string]any)
		if item["type"] == "error" || item["type"] == "agent_message" {
			continue
		}
		if item != nil {
			typ += ":" + item["type"].(string)
		}
		out = append(out, typ)
	}
	return out
}

