package subagents

import (
	"context"
	"os"
	"time"

	"github.com/sloprail/harness-mocks/internal/scenario"
)

// EnvScript names the scenario script a sub-agent runs when its launching call
// does not name one.
const EnvScript = "A10N_MOCK_SUBAGENT_SCRIPT"

// Run is a sub-agent running for its parent: started now, and finished when
// its final report is in.
type Run struct {
	done chan Report
}

// Report is how a sub-agent's run ended: its final report (the last thing it
// said) and how long it took.
type Report struct {
	Text     string
	Duration time.Duration
}

// Start launches a sub-agent: its scenario script (script, else the
// A10N_MOCK_SUBAGENT_SCRIPT of environ) is played, once, with prompt as the
// prompt it was given, and what it says last is its report. The mock models
// a sub-agent as the script's words alone: a tool call it makes is not run.
//
// sr:capability foreground-subagent-result
func Start(ctx context.Context, script, prompt, dir string, environ []string) *Run {
	if script == "" {
		for _, kv := range environ {
			if len(kv) > len(EnvScript) && kv[:len(EnvScript)+1] == EnvScript+"=" {
				script = kv[len(EnvScript)+1:]
			}
		}
		if script == "" {
			script = os.Getenv(EnvScript)
		}
	}
	r := &Run{done: make(chan Report, 1)}
	go func() {
		started := time.Now()
		var text string
		if t, err := scenario.RunTurn(ctx, script, dir, environ, scenario.Input{Prompt: prompt}); err == nil {
			for _, s := range t.Texts {
				text = s
			}
			if t.Result != nil && *t.Result != "" {
				text = *t.Result
			}
		}
		r.done <- Report{Text: text, Duration: time.Since(started)}
	}()
	return r
}

// Wait blocks until the sub-agent has finished and returns its report. A
// foreground sub-agent's parent waits here: it does nothing else until the
// report is in, and the report is the result of the call.
//
// sr:capability foreground-subagent-result
func (r *Run) Wait() Report {
	rep := <-r.done
	r.done <- rep
	return rep
}

// Foreground runs a sub-agent to its report, its parent blocked meanwhile.
//
// sr:capability foreground-subagent-result
func Foreground(ctx context.Context, script, prompt, dir string, environ []string) Report {
	return Start(ctx, script, prompt, dir, environ).Wait()
}
