package subagents

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func script(t *testing.T, body string) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), "sub.sh")
	require.NoError(t, os.WriteFile(p, []byte(body), 0o755))
	return p
}

const slowSub = `#!/bin/sh
sleep 0.3
printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"working"}]}}'
printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"REPORT:'"$A10N_MOCK_PROMPT"'"}]}}'
`

func TestForegroundBlocksUntilTheReportIsInAndTheReportIsWhatItSaidLast(t *testing.T) {
	s := script(t, slowSub)
	started := time.Now()
	rep := Foreground(context.Background(), s, "go", t.TempDir(), os.Environ())
	assert.Equal(t, "REPORT:go", rep.Text)
	assert.GreaterOrEqual(t, time.Since(started), 300*time.Millisecond)
	assert.GreaterOrEqual(t, rep.Duration, 300*time.Millisecond)
}

func TestStartReturnsAtOnceAndWaitGivesTheSameReportEachTime(t *testing.T) {
	s := script(t, slowSub)
	started := time.Now()
	run := Start(context.Background(), s, "x", t.TempDir(), os.Environ())
	assert.Less(t, time.Since(started), 250*time.Millisecond)
	assert.Equal(t, "REPORT:x", run.Wait().Text)
	assert.Equal(t, "REPORT:x", run.Wait().Text)
}

func TestTheScriptDefaultsToTheEnvironmentsSubAgentScript(t *testing.T) {
	s := script(t, slowSub)
	rep := Foreground(context.Background(), "", "y", t.TempDir(), append(os.Environ(), EnvScript+"="+s))
	assert.Equal(t, "REPORT:y", rep.Text)
}
EOF
