package events

// Collab is a call between agents as the stream shows it (recorded:
// runs/foreground-subagent-result): a collab_tool_call item of the tool that
// made it (spawn_agent, wait), the thread that called, the agents it names and
// their states.
type Collab struct {
	Tool, Sender, Prompt string
	Receivers            []string
	// States is each receiver's state: its status, and the message it came
	// with (the report, once it has completed).
	States map[string]CollabState
}

// CollabState is one agent's state in a collab call.
type CollabState struct {
	Status  string
	Message *string
}

func (c Collab) item(id, status string) map[string]any {
	var prompt any
	if c.Prompt != "" {
		prompt = c.Prompt
	}
	states := map[string]any{}
	for k, v := range c.States {
		var msg any
		if v.Message != nil {
			msg = *v.Message
		}
		states[k] = map[string]any{"status": v.Status, "message": msg}
	}
	receivers := c.Receivers
	if receivers == nil {
		receivers = []string{}
	}
	return map[string]any{"id": id, "type": "collab_tool_call", "tool": c.Tool, "sender_thread_id": c.Sender,
		"receiver_thread_ids": receivers, "prompt": prompt, "agents_states": states, "status": status}
}

// CollabStarted reports a call between agents that began; the id pairs it
// with its end.
func (s *Stream) CollabStarted(c Collab) string {
	id := s.newID()
	s.emit(map[string]any{"type": "item.started", "item": c.item(id, "in_progress")})
	return id
}

// CollabCompleted reports how a started call between agents ended.
func (s *Stream) CollabCompleted(id string, c Collab) {
	s.emit(map[string]any{"type": "item.completed", "item": c.item(id, "completed")})
}

