package runner

import (
	"context"
	"encoding/json"
	"sync"

	"github.com/sloprail/harness-mocks/codex-mock/internal/events"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/scenario"
	"github.com/sloprail/harness-mocks/internal/subagents"
)

// The tools that run a sub-agent. Codex hands the parent no result when it
// spawns one: the call returns the agent's id at once, and the parent's own
// wait call blocks until the sub-agent has finished and returns its report
// (recorded: runs/foreground-subagent-result).
const (
	toolSpawnAgent = "spawn_agent"
	toolWaitAgent  = "wait_agent"
	agentNickname  = "Mock"
)

// children are the sub-agents this run has spawned, by their thread id.
var children = struct {
	sync.Mutex
	runs map[string]*subagents.Run
}{runs: map[string]*subagents.Run{}}

func isAgentTool(name string) bool { return name == toolSpawnAgent || name == toolWaitAgent }

// agentCall carries out a spawn_agent or wait_agent call of the script.
//
// sr:provides foreground-subagent-result/codex
func (h turnHost) agentCall(ctx context.Context, tu scenario.ToolUse) {
	h.rollout.ToolCall(tu.ID, tu.Name, tu.Input)
	var in struct {
		Message string   `json:"message"`
		Script  string   `json:"script"`
		Targets []string `json:"targets"`
	}
	_ = json.Unmarshal(tu.Input, &in)
	var out any
	if tu.Name == toolSpawnAgent {
		out = h.spawn(ctx, in.Message, in.Script)
	} else {
		out = h.wait(in.Targets)
	}
	b, _ := json.Marshal(out)
	h.rollout.ToolOutput(tu.ID, string(b))
}

// spawn starts the sub-agent and returns its id at once, with the name Codex
// gives it.
func (h turnHost) spawn(ctx context.Context, prompt, script string) map[string]string {
	call := events.Collab{Tool: "spawn_agent", Sender: h.id, Prompt: prompt}
	item := h.events.CollabStarted(call)
	id := coresession.NewID()
	children.Lock()
	children.runs[id] = subagents.Start(ctx, script, prompt, h.cfg.Cwd, h.toolEnv)
	children.Unlock()
	call.Receivers = []string{id}
	call.States = map[string]events.CollabState{id: {Status: "pending_init"}}
	h.events.CollabCompleted(item, call)
	return map[string]string{"agent_id": id, "nickname": agentNickname}
}

// wait blocks until every sub-agent it names has finished, and returns each's
// report.
func (h turnHost) wait(targets []string) map[string]any {
	call := events.Collab{Tool: "wait", Sender: h.id, Receivers: targets}
	item := h.events.CollabStarted(events.Collab{Tool: "wait", Sender: h.id, Receivers: targets})
	call.States = map[string]events.CollabState{}
	status := map[string]any{}
	for _, id := range targets {
		children.Lock()
		run := children.runs[id]
		children.Unlock()
		if run == nil {
			status[id] = map[string]any{"not_found": true}
			continue
		}
		report := run.Wait().Text
		call.States[id] = events.CollabState{Status: "completed", Message: &report}
		status[id] = map[string]any{"completed": report}
	}
	h.events.CollabCompleted(item, call)
	return map[string]any{"status": status, "timed_out": false}
}

