)

// toolTask is the tool that runs a sub-agent.
const toolTask = "Task"

// task carries out a Task call of the script: a foreground sub-agent. The
// parent blocks until it has finished; the call's completed frame then holds
// its report as the call's result, with the sub-agent's id, that it did not run
// in the background and how long it took (recorded:
// runs/foreground-subagent-result). The sub-agent keeps its own transcript,
// beside the session's.
//
// sr:provides foreground-subagent-result/cursor
func (s *session) task(ctx context.Context, tu scenario.ToolUse) {
	var in struct {
		Description string `json:"description"`
		Prompt      string `json:"prompt"`
		Script      string `json:"script"`
	}
	_ = json.Unmarshal(tu.Input, &in)
	args := map[string]any{
		"description": in.Description, "prompt": in.Prompt, "subagentType": map[string]any{"unspecified": map[string]any{}},
		"model": "default", "agentId": coresession.NewID(), "attachments": []any{}, "mode": "TASK_MODE_UNSPECIFIED",
		"respondingToMessageIds": []any{}, "environment": "SUBAGENT_EXECUTION_ENVIRONMENT_UNSPECIFIED",
		"machine": map[string]any{"sameMachine": map[string]any{}},
	}
	call := toolexec.Call{Kind: "taskToolCall", Args: args}
	s.forward(startedFrame(s.id, tu.ID, call))
	s.tr.toolUse(toolTask, map[string]any{"description": in.Description, "prompt": in.Prompt,
		"subagent_type": "generalPurpose", "run_in_background": false})

	report := subagents.Foreground(ctx, in.Script, in.Prompt, s.cfg.Dir, s.cfg.Environ)

	id := coresession.NewID()
	if sub, err := newTranscript(s.cfg.Home, s.cfg.Dir, id); err == nil {
		sub.user(in.Prompt)
		sub.text(report.Text)
		sub.end()
	}
	s.forward(completedFrame(s.id, tu.ID, call, map[string]any{"success": map[string]any{
		"conversationSteps": []any{map[string]any{"assistantMessage": map[string]any{"text": report.Text}}},
		"agentId":           id, "isBackground": false, "durationMs": strconv.FormatInt(report.Duration.Milliseconds(), 10),
		"backgroundReason": "SUBAGENT_BACKGROUND_REASON_UNSPECIFIED"}}))
}

