	for _, e := range events {
		if item, _ := e["item"].(map[string]any); item["type"] == "collab_tool_call" {
			out = append(out, map[string]any{"phase": e["type"], "item": item})
		}
	}
	return
}

const spawnThenWait = `#!/bin/sh
n=$(grep -c function_call_output "$A10N_MOCK_SESSION_FILE")
if [ "$n" = 0 ]; then
  printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"call_0","name":"spawn_agent","input":{"message":"Reply with exactly the word PINEAPPLE-7 and nothing else.","script":"sub.sh"}}]}}'
  exit 0
fi
if [ "$n" = 1 ]; then
  id=$(jq -r 'select(.payload.type=="function_call_output") | .payload.output' "$A10N_MOCK_SESSION_FILE" | head -n1 | jq -r .agent_id)
  printf '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"call_1","name":"wait_agent","input":{"targets":["%s"],"timeout_ms":3600000}}]}}\n' "$id"
  exit 0
fi
printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"PINEAPPLE-7"}]}}' '{"type":"result","subtype":"success","result":"PINEAPPLE-7"}'
`

const slowSubAgent = `#!/bin/sh
sleep 0.4
printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"PINEAPPLE-7"}]}}'
`

// A sub-agent is spawned and waited for, as the recording shows: spawn_agent
// returns at once with the sub-agent's id (its state pending), and the
// parent's wait call blocks until the sub-agent has finished, then hands back
// its final report as that call's result, with the sub-agent's status. The
// stream's items carry the recorded fields; the sub-agent's report is also
// what the parent was told. The recording has no usage trailer, and the mock
// adds none.
// sr:proves foreground-subagent-result/codex
func TestASpawnedSubAgentIsWaitedForAndItsReportIsTheWaitResult(t *testing.T) {
	rec := loadRecording(t, "foreground-subagent-result")
	want := collabCalls(jsonLines(readFile(t, filepath.Join(rec.sample, "stream.jsonl"))))
	require.Len(t, want, 4)

	got := execMock(t, scenario{Script: spawnThenWait, Files: map[string]string{"sub.sh": slowSubAgent},
		Prompt: "Spawn one sub-agent and wait for it."})
	require.Equal(t, 0, got.Code, got.Stderr)
	calls := collabCalls(got.stream())
	require.Len(t, calls, 4)

	// same phases, tools and fields as the recording, item by item
	for i := range want {
		wi, gi := want[i]["item"].(map[string]any), calls[i]["item"].(map[string]any)
		assert.Equal(t, want[i]["phase"], calls[i]["phase"])
		assert.Equal(t, wi["tool"], gi["tool"])
		assert.Equal(t, wi["status"], gi["status"])
		assert.Equal(t, keys(wi), keys(gi))
		assert.Equal(t, len(wi["receiver_thread_ids"].([]any)), len(gi["receiver_thread_ids"].([]any)), "receivers of item %d", i)
		assert.Equal(t, wi["prompt"] == nil, gi["prompt"] == nil)
	}

	// spawn answers at once: the sub-agent's state is pending
	spawned := calls[1]["item"].(map[string]any)
	child := spawned["receiver_thread_ids"].([]any)[0].(string)
	assert.Equal(t, "pending_init", spawned["agents_states"].(map[string]any)[child].(map[string]any)["status"])
	assert.Equal(t, "Reply with exactly the word PINEAPPLE-7 and nothing else.", spawned["prompt"])

	// the wait ends with the sub-agent completed, its report the message
	waited := calls[3]["item"].(map[string]any)["agents_states"].(map[string]any)[child].(map[string]any)
	assert.Equal(t, map[string]any{"status": "completed", "message": "PINEAPPLE-7"}, waited)

	// the parent was told that report as the wait's result
	rollout := got.rollout(t)
	assert.Contains(t, rollout, `{\"status\":{\"`+child+`\":{\"completed\":\"PINEAPPLE-7\"}},\"timed_out\":false}`)
}

func keys(m map[string]any) (ks []string) {
	for k := range m {
		ks = append(ks, k)
	}
	sortStrings(ks)
	return
}

