// agentTool is Codex's tool that dispatches a sub-agent. It needs a message
// (Codex also takes a list of items in its place; the mock does not model
// that): subagents.MessageRequired.
const agentTool = "spawn_agent"

// agentRequired is what a dispatch must carry, as the core checks it.
var agentRequired = subagents.MessageRequired

// spawnRefusal is what Codex tells the agent of a spawn_agent call that
// carries none of what it needs.
const spawnRefusal = "Provide one of: message or items"

// hookName is the tool's name in the hooks' payloads.
func hookName(c toolcall.Call) string {
	if c.Name == agentTool {
		return agentTool
	}
	return toolName
}

// InputCheckedLate: Codex checks a dispatch's input only after the PreToolUse
// hook has seen the call, even one that carries nothing; the call is then
// refused with spawnRefusal, nothing runs and no PostToolUse hook fires
// (recorded: runs/agent-input-validation). The shell tool's input is checked
// first.
// sr:provides agent-input-validation/codex
func (h toolHost) InputCheckedLate(name string) bool { return name == agentTool }
package events

// AgentState is how a sub-agent stands in a collab_tool_call item.
type AgentState struct {
	Status  string `json:"status"`
	Message any    `json:"message"`
}

// CollabStarted reports a call that manages sub-agents (spawn_agent, wait)
// that began; the id pairs it with its end. prompt is nil when the call has
// none.
func (s *Stream) CollabStarted(tool, sender string, receivers []string, prompt any) string {
	id := s.newID()
	s.emit(map[string]any{"type": "item.started", "item": collabItem(id, tool, sender, receivers, prompt,
		map[string]AgentState{}, "in_progress")})
	return id
}

// CollabCompleted reports how that call ended: the sub-agents it concerns and
// how each stands (recorded: runs/subagent-lifecycle-hooks).
func (s *Stream) CollabCompleted(id, tool, sender string, receivers []string, prompt any, states map[string]AgentState) {
	s.emit(map[string]any{"type": "item.completed", "item": collabItem(id, tool, sender, receivers, prompt, states, "completed")})
}

func collabItem(id, tool, sender string, receivers []string, prompt any, states map[string]AgentState, status string) map[string]any {
	if receivers == nil {
		receivers = []string{}
	}
	return map[string]any{"id": id, "type": "collab_tool_call", "tool": tool, "sender_thread_id": sender,
		"receiver_thread_ids": receivers, "prompt": prompt, "agents_states": states, "status": status}
}
